import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.VvOSaRrC.js";const k=JSON.parse('{"title":"KRoot-ADK Commands","description":"","frontmatter":{},"headers":[],"relativePath":"en/commands.md","filePath":"en/commands.md"}'),r={name:"en/commands.md"};function s(i,t,n,c,l,p){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="kroot-adk-commands" tabindex="-1">KRoot-ADK Commands <a class="header-anchor" href="#kroot-adk-commands" aria-label="Permalink to &quot;KRoot-ADK Commands&quot;">​</a></h1><p>This page lists the slash commands that are actually shipped in <code>templates/.claude/commands/kroot/</code>.</p><h2 id="claude-code-slash-commands" tabindex="-1">Claude Code Slash Commands <a class="header-anchor" href="#claude-code-slash-commands" aria-label="Permalink to &quot;Claude Code Slash Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/kroot:architect</code></td><td>Architecture review, ADRs, and system design checks</td></tr><tr><td><code>/kroot:build-fix</code></td><td>Build, type, and runtime error repair</td></tr><tr><td><code>/kroot:classify</code></td><td>Classify a task and route it to the right workflow</td></tr><tr><td><code>/kroot:cleanup</code></td><td>Safe cleanup and dead-code removal</td></tr><tr><td><code>/kroot:codemap</code></td><td>Generate or refresh codebase architecture maps</td></tr><tr><td><code>/kroot:docs</code></td><td>Update README, API docs, changelog, and code comments</td></tr><tr><td><code>/kroot:e2e</code></td><td>Create and run browser E2E tests</td></tr><tr><td><code>/kroot:eval</code></td><td>Run evaluation-driven checks</td></tr><tr><td><code>/kroot:github</code></td><td>Work with GitHub issues and pull requests</td></tr><tr><td><code>/kroot:jarvis</code></td><td>Autonomous development orchestration</td></tr><tr><td><code>/kroot:learn</code></td><td>Explore and summarize the codebase</td></tr><tr><td><code>/kroot:loop</code></td><td>Ralph Loop style iterative repair</td></tr><tr><td><code>/kroot:perspective</code></td><td>Multi-perspective review</td></tr><tr><td><code>/kroot:poc</code></td><td>POC-first greenfield development</td></tr><tr><td><code>/kroot:pr-lifecycle</code></td><td>PR creation, CI monitoring, review handling, and merge flow</td></tr><tr><td><code>/kroot:refactor</code></td><td>Refactoring with behavior preservation</td></tr><tr><td><code>/kroot:security</code></td><td>Security review and dependency checks</td></tr><tr><td><code>/kroot:test</code></td><td>Test generation and execution</td></tr><tr><td><code>/kroot:verify</code></td><td>Build, lint, test, security, and browser verification</td></tr></tbody></table><h2 id="kroot-pipeline" tabindex="-1">KRoot Pipeline <a class="header-anchor" href="#kroot-pipeline" aria-label="Permalink to &quot;KRoot Pipeline&quot;">​</a></h2><p>The 13-stage KRoot Pipeline is driven by the <code>kroot-workflow-pipeline</code> skill, not by old numbered slash commands.</p><p>Ask Claude Code in natural language, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KRoot Pipeline으로 새 프로젝트 시작해줘.</span></span>
<span class="line"><span>S01 요구사항 분석 단계 실행해줘.</span></span>
<span class="line"><span>S09 프론트엔드 구현 단계 진행해줘.</span></span></code></pre></div><p>Before a stage agent is called, the orchestrator must validate that the stage is active:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kroot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> S01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>If the stage is not active for the current project workflow, the agent must not run and the user should be told that the current stage is not active.</p><h2 id="cli-commands" tabindex="-1">CLI Commands <a class="header-anchor" href="#cli-commands" aria-label="Permalink to &quot;CLI Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>kroot init</code></td><td>Install KRoot templates into a project</td></tr><tr><td><code>kroot update --sync-templates</code></td><td>Update installed project templates from the embedded templates</td></tr><tr><td><code>kroot auth login</code></td><td>Authenticate with kroot-server</td></tr><tr><td><code>kroot workflow ...</code></td><td>Select and validate project workflow stages</td></tr><tr><td><code>kroot skill ...</code></td><td>List, search, and inspect skills</td></tr><tr><td><code>kroot hooks ...</code></td><td>Claude Code hook entrypoints</td></tr><tr><td><code>kroot webchat start</code></td><td>Start browser-based webchat</td></tr><tr><td><code>kroot worktree ...</code></td><td>Manage Git worktrees</td></tr><tr><td><code>kroot router ...</code></td><td>Manage LLM provider routing</td></tr><tr><td><code>kroot doctor</code></td><td>Run diagnostics</td></tr><tr><td><code>kroot statusline</code></td><td>Render Claude Code status line</td></tr></tbody></table><p>Run <code>kroot help</code> for the complete CLI command tree.</p>`,14)])])}const m=e(r,[["render",s]]);export{k as __pageData,m as default};
